import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"8、【比】 坤下坎上","description":"周易口诀义 - 8、【比】 坤下坎上","frontmatter":{"title":"8、【比】 坤下坎上","description":"周易口诀义 - 8、【比】 坤下坎上"},"headers":[],"relativePath":"zh/classics/koujueyi/010.md","filePath":"zh/classics/koujueyi/010.md"}'),r={name:"zh/classics/koujueyi/010.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_8、【比】-坤下坎上" tabindex="-1">8、【比】 坤下坎上 <a class="header-anchor" href="#_8、【比】-坤下坎上" aria-label="Permalink to “8、【比】 坤下坎上”">​</a></h1><p>彖曰：比，吉也。比，辅也，下顺从也。「原筮元永贞无咎」，以刚中也。「不宁方来」，上下应也。「后夫凶」，其道穷也。象曰：地上有水，「比」。先王以建万国，亲诸侯。</p><p>初六：有孚比之，无咎。有孚盈缶，终来有他，吉。</p><p>象曰：比之初六，「有他吉」也。</p><p>六二：比之自内，贞吉。</p><p>象曰：「比之自内」，不自失也。</p><p>六三：比之匪人。</p><p>象曰：「比之匪人」，不亦伤乎！</p><p>六四：外比之，贞吉。</p><p>象曰：「外比」于贤，以从上也。</p><p>九五：显比，王用三驱，失前禽。邑人不诫，吉。</p><p>象曰：「显比」之吉，位正中也。舍逆取顺，「失前禽」也。「邑人不诫」，上使中也。</p><p>上六：比之无首，凶。</p><p>象曰：「比之无首」，无所终也。</p><p>解读</p><p>「比吉，原筮元永贞无咎」者，「比」是亲比之义，与人亲比，自然获吉，故曰「比吉」也。与人亲比，必须寻其根源。筮是问也，审其情原，方得「大永贞」，是贞正之人与之亲比，乃得「无咎」。若遇奸邪之人，则不能保其亲比之道。「不宁方来」者，「比」是宁乐之时，亦犹人君有德，不宁之方，悉来归化焉。「后夫凶」者，「比」道宜速，若处后而来，被人疏隔，所以「凶」也。</p><p>象曰：「地上有水，比，先王以建万国，亲诸侯」者，子夏传云「地得水而柔，水得地而流」是也。「先王以建万国，亲诸侯」者，万方各据境域，谓王者封建有功之臣也。「亲诸侯」，谓爵赏及亲友，令助君之化也。</p><p>初六，有孚比之，无咎。有孚盈缶，终来有他，吉者，处比之初，唯须以信待物，先须以信，始得免咎，故曰「有孚比之，无咎」。初六既无偏应，来者皆与相亲，著信立诚，盈溢于质素之器，心无偏党，应者非一，故有他人而来，终亦不相拒，故有他吉。</p><p>「六二，比之自内，贞吉」者，专应于五，不能更比他人，劣于初六，故得当家内正之吉也。</p><p>「六三，比之匪人」者，匪，非也。处比之时，虽近二四，情不相得，二四柔謟，非己所亲，故曰「匪人」，谓非己亲比之人也。</p><p>「六四：外比之，贞吉」者，本应在初，初既远，即亲于所近，九五有德行，可以亲比之，故称「贞吉」也。</p><p>「九五：显比，王用三驱，失前禽，邑人不诫，吉」者，处比之时，居得尊位，固当心无偏党，来者比亲，而乃独应于二，显明亲比之道，是用心𥚹拘，故曰「显比」也。夫不能普及于物，而乃亲于二，亦如王用三驱，田猎相似。凡三驱之礼，受来恶去，故逆来趣己者舍之，背已而走者射之，故「失前禽」也。然有中正之德，不妄加之征伐，所有背叛，必须攻讨，以其当邑之人，不须防诫而得吉矣。独亲邑人，心不弘通，非君上之道可以为君上之使，故云「上使中」也。</p><p>「上六：比之无首，凶」者，处比之终，最在于外，众皆先至而相亲比，己独在后，违众叛义，所以「凶」也。若禹会诸侯于涂山，防风氏后至，禹乃戮之，此之谓也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
